-- ============================================================
-- Skill-matching schema + real seed data
-- Scope: persona / sub-persona / cross-persona classification only.
-- Band and location comparisons are deliberately NOT modeled here --
-- they're a separate concern in the existing engine and don't belong
-- in this demo.
-- ============================================================

BEGIN;

-- The three Phase 1 personas. Small, controlled vocabulary -- a real
-- lookup table beats a free-text column so a typo can't silently create
-- a fourth 'persona' that nothing else recognizes.
CREATE TABLE personas (
    persona_id   SERIAL PRIMARY KEY,
    persona_name TEXT NOT NULL UNIQUE
);


-- Sub-personas only exist under Frontend today (React/Angular/MERN/iOS/
-- Android, plus the dual-acceptable and framework-unconfirmed variants).
-- Fullstack Java/.NET employees and demands simply have no sub_persona_id.
CREATE TABLE sub_personas (
    sub_persona_id   SERIAL PRIMARY KEY,
    persona_id       INTEGER NOT NULL REFERENCES personas(persona_id),
    sub_persona_name TEXT NOT NULL,
    UNIQUE (persona_id, sub_persona_name)
);


-- Supply-side classification reference: the exact-match lookup table
-- that engine.py's SUPPLY_TABLE encoded as a Python dict. This is the
-- thing a reviewer edits by hand when a new Skill Cluster combination
-- shows up in an export -- no code change, no redeploy.
--
-- No FK from raw_skill_cluster anywhere to this table: a Skill Cluster
-- value that ISN'T a row here is itself meaningful (it's the
-- 'UNCLASSIFIED -- not in reference table' state), not a data error,
-- so it must be representable, not blocked by a constraint.
CREATE TABLE skill_cluster_rules (
    raw_skill_cluster       TEXT PRIMARY KEY,
    persona_id              INTEGER REFERENCES personas(persona_id),
    sub_persona_id          INTEGER REFERENCES sub_personas(sub_persona_id),
    named_accessories       TEXT[],
    completeness            TEXT,
    cross_persona_accessory TEXT,
    status                  TEXT
);


-- Demand-side vocabulary used by the free-text parser (classify_demand_row).
-- The PARSING LOGIC stays as application code -- deciding a persona from an
-- arbitrary comma-separated phrase needs real branching (anchor precedence,
-- dual-acceptable exceptions, etc.), not a lookup. But the vocabulary it
-- reads from -- which literal tokens count as a Java anchor, a React
-- framework signal, an out-of-scope skill -- shouldn't be a Python set
-- literal either. This table is that vocabulary.
CREATE TABLE skill_tokens (
    token    TEXT PRIMARY KEY,
    category TEXT NOT NULL
);


-- Supply side, skill-relevant columns only (band/location intentionally
-- excluded from this demo -- see the note at the top of the file).
CREATE TABLE supply_employees (
    employee_code           BIGINT PRIMARY KEY,
    employee_name           TEXT NOT NULL,
    raw_skill_cluster       TEXT,   -- free text as exported; NOT a FK, see skill_cluster_rules note
    persona_id              INTEGER REFERENCES personas(persona_id),
    sub_persona_id          INTEGER REFERENCES sub_personas(sub_persona_id),
    completeness            TEXT,
    named_accessories       TEXT[],
    cross_persona_accessory TEXT
);


-- Demand side, skill-relevant columns only (same scope note as above).
CREATE TABLE demand_positions (
    job_req_id              TEXT PRIMARY KEY,  -- not all IDs are numeric (e.g. 'HCL/DBS/2026/2820615')
    raw_skill_cluster       TEXT,   -- Final Skill Cluster, free text as exported
    persona_id              INTEGER REFERENCES personas(persona_id),
    sub_persona_id          INTEGER REFERENCES sub_personas(sub_persona_id),
    cross_persona_accessory TEXT
);


COMMIT;

-- ============================================================
-- Sample queries: how a skill match is found
-- ============================================================

-- 1) Same-persona candidates for one employee -- the main case.
--    (This is what build_candidate_demands() calls the 'same persona
--    family' case: Java-with-Java, .NET-with-.NET, Frontend-with-Frontend.)
SELECT e.employee_code, e.employee_name, e.raw_skill_cluster AS employee_cluster,
       d.job_req_id, d.raw_skill_cluster AS demand_cluster
FROM supply_employees e
JOIN demand_positions d ON d.persona_id = e.persona_id
WHERE e.employee_code = 52170543  -- Agunuri Deepthi, from the earlier examples
ORDER BY d.job_req_id;

-- 2) Cross-persona discount candidates -- an employee whose persona is
--    Fullstack Java/.NET but who has a NAMED Frontend accessory (e.g. React)
--    can be a discounted candidate for a standalone demand asking for just
--    that framework. This is the join that finds those pairs.
SELECT e.employee_code, e.employee_name, p.persona_name AS employee_persona,
       e.cross_persona_accessory, d.job_req_id, d.raw_skill_cluster AS demand_cluster,
       sp.sub_persona_name AS demand_sub_persona
FROM supply_employees e
JOIN personas p ON p.persona_id = e.persona_id
JOIN demand_positions d ON d.persona_id = (SELECT persona_id FROM personas WHERE persona_name = 'Frontend')
JOIN sub_personas sp ON sp.sub_persona_id = d.sub_persona_id
WHERE e.cross_persona_accessory IS NOT NULL
  AND e.cross_persona_accessory = sp.sub_persona_name
ORDER BY e.employee_code, d.job_req_id
LIMIT 20;

-- 3) Both cases combined -- the full skill-level candidate pool for one
--    employee, same/persona plus cross-persona discount, with a flag saying
--    which case produced the row. (Band, location, and the final
--    Strong/Good/Weak/Excluded tiering are NOT computed here -- that stays
--    in build_matches.py, on purpose; see the note at the top of this file.)
SELECT d.job_req_id, d.raw_skill_cluster AS demand_cluster, 'same_persona' AS match_type
FROM supply_employees e
JOIN demand_positions d ON d.persona_id = e.persona_id
WHERE e.employee_code = 52170543
UNION ALL
SELECT d.job_req_id, d.raw_skill_cluster, 'cross_persona_discount'
FROM supply_employees e
JOIN sub_personas sp ON sp.sub_persona_name = e.cross_persona_accessory
JOIN demand_positions d ON d.sub_persona_id = sp.sub_persona_id
WHERE e.employee_code = 52170543
  AND e.cross_persona_accessory IS NOT NULL
ORDER BY 1;

-- 4) How many supply rows are unclassified (no persona) -- the data-quality
--    signal this table structure surfaces for free, just by persona_id IS NULL.
SELECT count(*) AS unclassified_supply_rows FROM supply_employees WHERE persona_id IS NULL;